        // Changing settings
        gateway.set_operation_mode(OperationMode::Maintenance);
        gateway.set_transmission_interval(300);

        // Reactivating
        gateway.activate_device();
        std::cout << "[Success] Configuration applied and device reactivated successfully!\n";
        gateway.info();

